def max_digit_sum(x):
    x_str = str(x)
    n = len(x_str)

    # Start with the largest possible number with the same length as x
    result = ['9'] * n

    for i in range(n):
        if int(''.join(result)) > x:
            # If the current result exceeds x, adjust the digits
            if i == 0:
                # If we're at the most significant digit, we can only use the first digit of x
                result[i] = x_str[i]
            else:
                # Otherwise, reduce the current digit and adjust the rest
                result[i] = str(int(x_str[i]) - 1)
                for j in range(i + 1, n):
                    result[j] = '9'

        # If the current result is equal to x, we can stop
        if int(''.join(result)) == x:
            break

    return ''.join(result)

